package com.phoenix.business.security;
import com.phoenix.business.repository.*; import io.jsonwebtoken.Claims; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component @RequiredArgsConstructor public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; private final RevokedTokenRepository revoked; @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{Claims c=jwt.parse(h.substring(7)); if(!revoked.existsById(c.getId())) users.findByUsernameIgnoreCase(c.getSubject()).filter(u->u.isActive()).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getUsername(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name())))));}catch(Exception ignored){} chain.doFilter(req,res);} }
